<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{PlatformInvoice,SubscriptionPlan,TenantSubscription}; use App\Services\{AuditLogger,SubscriptionService}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
final class PlatformBillingController { public function plans(){return response()->json(['data'=>SubscriptionPlan::with('features')->where('is_active',true)->orderBy('monthly_price')->get()]);} public function storePlan(Request $r,AuditLogger $audit){$d=$r->validate(['code'=>'required|alpha_dash|max:40','name'=>'required|string|max:100','description'=>'nullable|string','currency_code'=>'required|string|size:3','monthly_price'=>'required|numeric|min:0','annual_price'=>'required|numeric|min:0','features'=>'nullable|array']);$plan=DB::transaction(function()use($d){$plan=SubscriptionPlan::create($d);foreach($d['features']??[] as $feature) $plan->features()->create(['feature_key'=>$feature['key'],'value'=>(string)$feature['value'],'value_type'=>$feature['type']??'boolean']);return $plan->load('features');});$audit->record($r,'platform.subscription_plan.created',null,$plan);return response()->json(['data'=>$plan],201);} public function subscriptions(){return response()->json(['data'=>TenantSubscription::with(['plan'])->with('tenant')->latest()->paginate(50)]);} public function revenue(){return response()->json(['data'=>['invoiced'=>PlatformInvoice::whereIn('status',['open','paid'])->sum('total'),'paid'=>PlatformInvoice::where('status','paid')->sum('paid_total'),'past_due'=>PlatformInvoice::where('status','past_due')->sum('total')]]);} public function webhook(Request $r,string $provider,SubscriptionService $billing){$payload=json_decode($r->getContent(),true,512,JSON_THROW_ON_ERROR);$event=$billing->webhook($provider,$r->getContent(),(string)$r->header('X-Billing-Signature'),$payload);return response()->json(['data'=>$event->only(['provider','provider_event_id','state'])]);} }
